package co.com.empresa.infrastructure.controller.typecategory;import co.com.empresa.application.typecategory.TypeCategoryRequestDto;import co.com.empresa.application.typecategory.TypeCategoryResponseDto;import co.com.empresa.application.typecategory.TypeCategoryUseCase;import co.com.empresa.commons.helper.ApiResponseBuilder;import co.com.empresa.commons.services.i18.MessageService;import co.com.empresa.infrastructure.typecategory.TypeCategoryRestController;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDateTime;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class)class TypeCategoryRestControllerTest {    @Mock    private TypeCategoryUseCase typeCategoryUseCase;    @Mock    private MessageService messageService;    @Mock    private ApiResponseBuilder responseBuilder;    @InjectMocks    private TypeCategoryRestController typeCategoryRestController;    private TypeCategoryRequestDto requestDto;    private TypeCategoryResponseDto responseDto;    @BeforeEach    void setUp() {        requestDto = new TypeCategoryRequestDto(null, "Category Name", "CAT-001", "Category Description", true);        responseDto = new TypeCategoryResponseDto(1L, "Category Name", "CAT-001", "Category Description", true, "system", LocalDateTime.now(), null, null);    }    @Test    @DisplayName("create: Should return created category")    void create_ReturnsCreated() {        when(typeCategoryUseCase.create(any())).thenReturn(responseDto);        when(messageService.getMessage(anyString())).thenReturn("Success");        when(responseBuilder.success(any(), anyString())).thenReturn(null);        var result = typeCategoryRestController.create(requestDto);        verify(typeCategoryUseCase).create(any());    }    @Test    @DisplayName("getById: Should return category when exists")    void getById_ReturnsCategory() {        Long id = 1L;        when(typeCategoryUseCase.getById(id)).thenReturn(responseDto);        when(messageService.getMessage(anyString())).thenReturn("Success");        when(responseBuilder.success(any(), anyString())).thenReturn(null);        var result = typeCategoryRestController.getById(id);        verify(typeCategoryUseCase).getById(id);    }}